using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Text;
using System.Threading.Tasks;

namespace AntiGravityRepeater {
public static partial class Diagnostics {
 static byte[] Join(params byte[][] parts){return parts.SelectMany(x=>x).ToArray();}
 static byte[] Var(ulong v){var b=new List<byte>();do{byte x=(byte)(v&127);v>>=7;if(v!=0)x|=128;b.Add(x);}while(v!=0);return b.ToArray();}
 static byte[] Pb(int id,byte[] value){return Join(Var((ulong)((id<<3)|2)),Var((ulong)value.Length),value);}
 static byte[] Txt(int id,string text){return Pb(id,Encoding.UTF8.GetBytes(text));}
 static byte[] Topic(string key,byte[] value){return Pb(1,Join(Txt(1,key),Pb(2,Txt(1,Convert.ToBase64String(value)))));}
 static string B64(byte[] b){return Convert.ToBase64String(b);}
 static LoginAccount FakeAccount(string email,double remaining){var qi=Join(new byte[]{13},BitConverter.GetBytes((float)remaining),Pb(2,Join(new byte[]{8},Var(1792580000))));var model=Join(Txt(1,"Test model"),Pb(2,new byte[]{8,7}),Pb(15,qi));var status=Join(Txt(3,"Test"),Txt(7,email),Pb(33,Pb(1,model)));var oauth=Join(Txt(1,"FAKE_ACCESS_TEST_ONLY_"+email),Txt(2,"Bearer"),Txt(3,"FAKE_REFRESH_TEST_ONLY_"+email));var records=new Dictionary<string,string>{{LoginState.Prefix+"oauthToken",B64(Topic("oauthTokenInfoSentinelKey",oauth))},{LoginState.Prefix+"userStatus",B64(Topic("userStatusSentinelKey",status))}};return new LoginAccount{Email=email,Name="Test",SavedUtc=DateTime.UtcNow,Usage=UsageSnapshot.FromTopic(records[LoginState.Prefix+"userStatus"]),Records=records};}
 static void AccountUnitTests(){
  Assert(UsageSnapshot.Fraction(null,false)==null,"missing quota stays unknown");Assert(UsageSnapshot.Fraction(null,true)==0,"protobuf omitted fraction is zero when quota exists");Assert(UsageSnapshot.Fraction("invalid",true)==null,"invalid quota stays unknown");Assert(UsageSnapshot.Fraction(2,true)==1,"quota is clamped at 100 percent");Assert(UsageSnapshot.Fraction(-1,true)==0,"negative quota clamps to zero");
  Assert(UsageSnapshot.ModelKeyFromRequest(new{cascadeConfig=new{plannerConfig=new{requestedModel=new{model="fixture-model"}}}})=="{\"model\":\"fixture-model\"}","anonymous send request resolves active model key");
  var u=UsageSnapshot.FromJson(Json.Decode("{\"userStatus\":{\"email\":\"fixture@example.invalid\",\"cascadeModelConfigData\":{\"clientModelConfigs\":[{\"label\":\"empty\",\"quotaInfo\":{}},{\"label\":\"unknown\"},{\"label\":\"half\",\"quotaInfo\":{\"remainingFraction\":0.5}}]}}}"));Assert(u.Models[0].Remaining==0,"JSON quota zero is not treated as unknown");Assert(!u.Models[1].Remaining.HasValue,"JSON absent quota is not treated as exhausted");Assert(u.Models[2].UsedText=="50%"&&u.Models[2].RemainingText=="50%","used and remaining quota displayed consistently");
  var a=FakeAccount("one@example.invalid",0);var b=FakeAccount("two@example.invalid",0.75);Assert(a.Usage.Email==a.Email,"persisted protobuf identity parsed");Assert(a.Usage.Models[0].Remaining==0,"persisted exhausted model parsed");Assert(Math.Abs(b.Usage.Models[0].Remaining.Value-0.75)<0.0001,"persisted fraction parsed");Assert(!string.IsNullOrEmpty(b.Usage.Models[0].ResetUtc),"persisted reset time parsed");
  Assert(RotationPolicy.Next(new[]{a,b},a.Email,"Test model",DateTime.UtcNow)==b,"exhaustion chooses another eligible account");Assert(RotationPolicy.Next(new[]{a},a.Email,"Test model",DateTime.UtcNow)==null,"current account is never selected again");Assert(RotationPolicy.Next(new[]{a,b},a.Email,"Other model",DateTime.UtcNow)==null,"rotation requires quota for the same model");Assert(RotationPolicy.Next(new[]{a,b},a.Email,"Test model",DateTime.UtcNow,new HashSet<string>{b.Id})==null,"attempted account cannot create a rotation loop");b.SavedUtc=DateTime.UtcNow.AddDays(-2);Assert(RotationPolicy.Next(new[]{a,b},a.Email,"Test model",DateTime.UtcNow)==null,"stale account quota is not used");b.SavedUtc=DateTime.UtcNow;b.Usage.Models[0].Disabled=true;Assert(RotationPolicy.Next(new[]{a,b},a.Email,"Test model",DateTime.UtcNow)==null,"disabled models are not eligible");b.Usage.Models[0].Disabled=false;Assert(!RotationPolicy.Exhausted(new ModelQuota()),"unknown quota does not trigger switching");Assert(RotationPolicy.Exhausted(a.Usage.Models[0]),"explicit zero quota triggers exhaustion policy");
  string folder=Path.Combine(Path.GetTempPath(),"AntiGravityRepeater-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var vault=new AccountVault();vault.Upsert(a);vault.Upsert(b);string vaultPath=Path.Combine(folder,"accounts.dpapi");vault.Save(vaultPath);var roundtrip=AccountVault.Load(vaultPath);Assert(roundtrip.Accounts.Count==2,"multiple logins survive encrypted persistence");Assert(roundtrip.Accounts[1].Records[LoginState.Prefix+"oauthToken"]==b.Records[LoginState.Prefix+"oauthToken"],"credential snapshot round-trip");Assert(!Encoding.UTF8.GetString(File.ReadAllBytes(vaultPath)).Contains(b.Records[LoginState.Prefix+"oauthToken"])&&!Encoding.UTF8.GetString(File.ReadAllBytes(vaultPath)).Contains(b.Email),"vault has no plaintext refresh token");byte[] corrupt=File.ReadAllBytes(vaultPath);corrupt[corrupt.Length/2]^=1;File.WriteAllBytes(vaultPath,corrupt);bool rejected=false;try{AccountVault.Load(vaultPath);}catch(InvalidDataException){rejected=true;}Assert(rejected,"tampered vault is rejected");Assert(File.ReadAllBytes(vaultPath).SequenceEqual(corrupt),"unreadable vault is preserved");
  string db=Path.Combine(folder,"fixture.vscdb");using(var state=new LoginState(db,true,true)){state.Execute("CREATE TABLE ItemTable(key TEXT PRIMARY KEY,value BLOB)");state.Set("unrelated.workspaces","must remain");state.ReplaceLogin(a.Records);Assert(state.Get(LoginState.Prefix+"oauthToken")==a.Records[LoginState.Prefix+"oauthToken"],"login transaction writes initial account");bool failed=false;try{state.ReplaceLogin(b.Records,()=>{throw new IOException("Injected test failure");});}catch(IOException){failed=true;}Assert(failed&&state.Get(LoginState.Prefix+"oauthToken")==a.Records[LoginState.Prefix+"oauthToken"],"partial switch rolls back original credentials");Assert(state.Get(LoginState.Prefix+"userStatus")==a.Records[LoginState.Prefix+"userStatus"],"rollback preserves matching identity");state.ReplaceLogin(b.Records);Assert(state.Get(LoginState.Prefix+"oauthToken")==b.Records[LoginState.Prefix+"oauthToken"],"transaction switches to second fixture account");Assert(state.Get("unrelated.workspaces")=="must remain","account switching preserves unrelated IDE data");var bad=new Dictionary<string,string>(a.Records);bad["unrelated.workspaces"]="bad";rejected=false;try{state.ReplaceLogin(bad);}catch(InvalidDataException){rejected=true;}Assert(rejected&&state.Get("unrelated.workspaces")=="must remain","arbitrary storage mutation is rejected");}
  bool launched=false;AccountSwitcher.CommitAndLaunch(db,a,()=>launched=true);Assert(launched&&LoginState.Capture(db).Email==a.Email,"switch workflow commits then launches the new fixture login");bool launchFailed=false;try{AccountSwitcher.CommitAndLaunch(db,b,()=>{throw new IOException("Injected launch failure");});}catch(IOException){launchFailed=true;}Assert(launchFailed&&LoginState.Capture(db).Email==a.Email,"launch failure restores previous fixture credentials");AccountSwitcher.CommitAndLaunch(db,b,()=>{});
  var imported=LoginState.Capture(db);Assert(imported.Email==b.Email,"login import agrees with committed identity");
  var ledger=new BudgetLedger();var before=new DateTime(2026,10,21,18,29,59,DateTimeKind.Utc);Assert(ledger.CanSend(1,before),"fresh daily budget is available");ledger.Day=UsageClock.Day(before);ledger.Attempted=1;Assert(!ledger.CanSend(1,before),"daily budget stops at limit");Assert(ledger.CanSend(0,before),"zero budget means unlimited");Assert(ledger.Used(before.AddSeconds(1))==0,"daily budget resets at midnight IST");
  Assert(RotationPolicy.CanSwitch(new[]{C("IDLE",1,"a")}),"switching is allowed only for idle agents");Assert(!RotationPolicy.CanSwitch(new[]{C("RUNNING",1,"a")}),"active agent blocks credential switching");Assert(!RotationPolicy.CanSwitch(new[]{C("UNSPECIFIED",1,"a")}),"unknown agent status blocks credential switching");
  var engine=new RepeatEngine{MaxRepeats=1};engine.Start();engine.MarkAccepted();engine.Stop("switching");engine.ResumeAfterAccountSwitch();Assert(engine.Sent==1,"switching accounts preserves repeat counter");Assert(!engine.Observe(C("IDLE",5,"a"),DateTime.UtcNow)&&!engine.Armed,"account switch cannot reset repeat limit");
  Console.WriteLine("PASS: "+assertions+" total assertions including usage, budget, vault and SQLite rollback");
 }
 static async Task LiveAccountsTest(){var endpoints=await Discovery.Find();try{Assert(endpoints.Count>0,"live account endpoint discovered");var saved=LoginState.Capture();UsageSnapshot live=null;foreach(var ep in endpoints){try{var candidate=UsageSnapshot.FromJson(await ep.Call("GetUserStatus",new{}));if(candidate.Models.Count>0&&string.Equals(candidate.Email,saved.Email,StringComparison.OrdinalIgnoreCase)){live=candidate;break;}}catch{}}Assert(live!=null&&live.Models.Count>0,"live per-model quota received");Assert(string.Equals(saved.Email,live.Email,StringComparison.OrdinalIgnoreCase),"local saved login matches live authenticated identity");Assert(saved.Records.ContainsKey(LoginState.Prefix+"oauthToken"),"reusable local login captured");var vault=AccountVault.Load();saved.Usage=live;vault.Upsert(saved);vault.Save();var restored=AccountVault.Load();Assert(restored.Accounts.Any(a=>a.Email==saved.Email&&a.Records[LoginState.Prefix+"oauthToken"]==saved.Records[LoginState.Prefix+"oauthToken"]),"real login encrypted and decrypted without exposing its keys");
  var report=new{result="PASS",testedAtUtc=DateTime.UtcNow.ToString("o"),assertions=assertions,liveModels=live.Models.Count,liveModelsWithQuota=live.Models.Count(m=>m.Remaining.HasValue),savedAccounts=restored.Accounts.Count,realLoginEncryptionVerified=true,fixtureTwoAccountSwitchVerified=true,fixtureRollbackVerified=true,realAlternateAccountSwitchTested=false,limitation="A second genuine account must be signed in by its owner before live cross-account switching can be verified."};Directory.CreateDirectory("tests");File.WriteAllText("tests/accounts-test-result.json",Json.Encode(report));Console.WriteLine(Json.Encode(report));
 }finally{foreach(var ep in endpoints)ep.Dispose();}}
}
}
